select
a.device_mete_id,
a.device_id,
a.custom_id,
a.mete_id,
a.mete_kind,
a.mete_type,
a.mete_name,
a.device_type,
a.position_type,
a.unit,
a.alarm_note,
a.alarm_type,
a.up_effect,
a.down_effect,
a.state_zero,
a.state_one,
a.alarm_state,
a.alarm_level,
a.high_limit1,
a.low_limit1,
a.high_limit2,
a.low_limit2,
a.high_limit3,
a.low_limit3,
a.high_limit4,
a.low_limit4,
a.alarm_delay,
a.alarm_cnt,
a.threshold_abs,
a.threshold_per,
a.modulus,
a.remark
from t_std_devicemete a
where 1 = 1
 and a.device_mete_id = #{deviceMeteId, jdbcType=BIGINT}
 and a.device_id = #{deviceId, jdbcType=BIGINT}
 and a.custom_id = #{customId, jdbcType=VARCHAR}
 and a.mete_id = #{meteId, jdbcType=BIGINT}
 and a.mete_kind = #{meteKind, jdbcType=VARCHAR}
 and a.mete_type = #{meteType, jdbcType=VARCHAR}
 and a.mete_name = #{meteName, jdbcType=VARCHAR}
 and a.device_type = #{deviceType, jdbcType=INTEGER}
 and a.position_type = #{positionType, jdbcType=VARCHAR}
 and a.unit = #{unit, jdbcType=VARCHAR}
 and a.alarm_note = #{alarmNote, jdbcType=VARCHAR}
 and a.alarm_type = #{alarmType, jdbcType=VARCHAR}
 and a.up_effect = #{upEffect, jdbcType=REAL}
 and a.down_effect = #{downEffect, jdbcType=REAL}
 and a.state_zero = #{stateZero, jdbcType=VARCHAR}
 and a.state_one = #{stateOne, jdbcType=VARCHAR}
 and a.alarm_state = #{alarmState, jdbcType=INTEGER}
 and a.alarm_level = #{alarmLevel, jdbcType=INTEGER}
 and a.high_limit1 = #{highLimit1, jdbcType=REAL}
 and a.low_limit1 = #{lowLimit1, jdbcType=REAL}
 and a.high_limit2 = #{highLimit2, jdbcType=REAL}
 and a.low_limit2 = #{lowLimit2, jdbcType=REAL}
 and a.high_limit3 = #{highLimit3, jdbcType=REAL}
 and a.low_limit3 = #{lowLimit3, jdbcType=REAL}
 and a.high_limit4 = #{highLimit4, jdbcType=REAL}
 and a.low_limit4 = #{lowLimit4, jdbcType=REAL}
 and a.alarm_delay = #{alarmDelay, jdbcType=INTEGER}
 and a.alarm_cnt = #{alarmCnt, jdbcType=INTEGER}
 and a.threshold_abs = #{thresholdAbs, jdbcType=NUMERIC}
 and a.threshold_per = #{thresholdPer, jdbcType=NUMERIC}
 and a.modulus = #{modulus, jdbcType=INTEGER}
 and a.remark = #{remark, jdbcType=VARCHAR}

